      "content": "{\n  \"name\": \"dsh-plugin-subscriptions\",\n  \"version\": \"0.9.11\",\n  \"description\": \"Use ChatGPT (Codex), Claude, Grok (X Premium), GitHub Copilot, and Google Antigravity subscriptions as DeepSeek Harness LLM providers, with OAuth login from the web Settings page\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/V1ki/dsh-plugin-subscriptions.git\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"llm\",\n    \"oauth\",\n    \"chatgpt\",\n    \"codex\",\n    \"claude\",\n    \"grok\",\n    \"github-copilot\",\n    \"google-antigravity\"\n  ],\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@10.26.2\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsc && tsdown\",\n    \"test\": \"tsc -p tsconfig.test.json && node --test \\\"lib-test/test/**/*.spec.js\\\"\",\n    \"prepare\": \"tsdown -c tsdown.prepare.config.ts\",\n    \"prepublishOnly\": \"pnpm build && pnpm test\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1 || 4.0.5-alpha.1 || 4.0.5-alpha.2\",\n    \"@deepseek-ai/dsh-attachment\": \"^0.1.1-rc.2 || ^0.1.2-alpha.1 || ^0.1.3-alpha.1 || ^0.1.5-alpha.1 || ^0.1.7-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-home-paths\": \"^0.1.1-rc.2 || ^0.1.2-alpha.1 || ^0.1.3-alpha.1 || ^0.1.5-alpha.1 || ^0.1.7-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.1-rc.2 || ^0.1.2-alpha.1 || ^0.1.3-alpha.1 || ^0.1.5-alpha.1 || ^0.1.7-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.1-rc.2 || ^0.1.2-alpha.1 || ^0.1.3-alpha.1 || ^0.1.5-alpha.1 || ^0.1.7-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-web\": \"^0.1.1-rc.2 || ^0.1.2-alpha.1 || ^0.1.3-alpha.1 || ^0.1.5-alpha.1 || ^0.1.7-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1 || 3.18.5-alpha.1 || 3.18.5-alpha.2\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-commands\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-invariants\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-util-values\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-web\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.7\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"tsdown\": \"^0.15.0\",\n    \"typescript\": \"^5.8.0\"\n  },\n  \"dependencies\": {\n    \"undici\": \"^7.0.0\"\n  },\n  \"pnpm\": {\n    \"packageExtensions\": {\n      \"@deepseek-ai/dsh-client-store@0.2.1-rc.2\": {\n        \"dependencies\": {\n          \"zustand\": \"~4.4.7\",\n          \"immer\": \"^10.1.1\"\n        }\n      },\n      \"@deepseek-ai/dsh-client-ui-primitives@0.2.1-rc.2\": {\n        \"dependencies\": {\n          \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.2\",\n          \"@deepseek-ai/dsh-util-code-language\": \"0.2.1-rc.2\",\n          \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.1-rc.2\",\n          \"@shikijs/langs\": \"^4.3.1\",\n          \"anser\": \"^2.3.5\",\n          \"clsx\": \"^2.0.0\",\n          \"diff\": \"^9.0.0\",\n          \"katex\": \"^0.16.47\",\n          \"mdast-util-from-markdown\": \"^2.0.3\",\n          \"mdast-util-gfm\": \"^3.1.0\",\n          \"mdast-util-math\": \"^3.0.0\",\n          \"micromark-core-commonmark\": \"^2.0.3\",\n          \"micromark-extension-gfm\": \"^3.0.0\",\n          \"micromark-extension-math\": \"^3.1.0\",\n          \"micromark-factory-space\": \"^2.0.1\",\n          \"micromark-util-character\": \"^2.1.1\",\n          \"micromark-util-classify-character\": \"^2.0.1\",\n          \"micromark-util-sanitize-uri\": \"^2.0.1\",\n          \"micromark-util-symbol\": \"^2.0.1\",\n          \"react\": \"^18.2.0\",\n          \"react-dom\": \"^18.2.0\",\n          \"shiki\": \"^4.3.1\",\n          \"simple-icons\": \"16.31.0\"\n        }\n      }\n    }\n  }\n}\n"
