      "path": "src/auth/rpc.ts",
      "content": "/**\n * The `subscriptions-auth` host RPC endpoints the web Settings page drives.\n * They are mounted as exact POST Fetch routes on the shared `/api` channel\n * (`/api/subscriptions-auth.<endpoint>`) and registered only when a host\n * `connection` service exists (the web profile); headless compositions load\n * the plugin without it. All business outcomes are returned as RpcResult\n * values; handlers never throw.\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { HostConnectionHandle } from '@deepseek-ai/dsh-client-connection'\nimport type { RpcResult } from '../compat.js'\nimport { AttachmentId } from '@deepseek-ai/dsh-attachment'\nimport type { ImageAttachmentRef } from '@deepseek-ai/dsh-attachment'\nimport { PROVIDER_IDS, type ProviderId } from './store.js'\nimport type { ProviderUsage } from '../providers/common.js'\nimport type { ProxyConfigView, ProxyDraft, ProxyInput, ProxyTestResult } from '../http.js'\nimport type { CliVersion } from '../providers/npm-cli-version.js'\n\n/** Internal endpoint dispatcher used after the host authenticates an exact Fetch route. */\nexport type SubscriptionsRpcHandler = (\n  endpoint: string,\n  payload: unknown,\n  signal: AbortSignal,\n) => Promise<RpcResult<unknown>>\n\n/**\n * Endpoint-name prefix under the shared `/api` channel: endpoint `status`\n * is served at `/api/subscriptions-auth.status`. The browser half calls\n * `rpc.call('/api', 'subscriptions-auth.status', payload)`.\n */\nexport const SUBSCRIPTIONS_AUTH_PREFIX = 'subscriptions-auth.'\n\n/**\n * Every endpoint {@link dispatch} answers; each gets one exact Fetch route.\n * Kept in one place so the route table and the switch cannot drift apart.\n */\nexport const SUBSCRIPTIONS_AUTH_ENDPOINTS = [\n  'providerSettings', 'setProviderSettings',\n  'status', 'login', 'manual', 'cancel', 'logout', 'setDefault', 'usage',\n  'image', 'video', 'prepareReset', 'consumeReset',\n  'speed', 'setSpeed',\n  'proxyGet', 'proxySet', 'proxyTest',\n  'modelDefaults', 'setModelDefault',\n] as const\n\n/** Media types the attachment store accepts (ImageMediaType). */\nconst IMAGE_MEDIA_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'] as const\n\n/** Decoded image bytes returned by the `image` endpoint. */\nexport interface ImageBytesResult {\n  mediaType: string\n  dataBase64: string\n}\n\n/** Decoded video bytes returned by the `video` endpoint. */\nexport interface VideoBytesResult {\n  mediaType: string\n  dataBase64: string\n}\n\n/** Bare MP4 file names the `video` endpoint accepts (no path separators). */\nconst VIDEO_NAME_PATTERN = /^[\\w.-]+\\.mp4$/\n\n/** One session's speed choice: standard routing or the fast (priority) tier. */\nexport type SpeedTier = 'standard' | 'fast'\n\n/** `speed` endpoint value: the session's choice plus the visibility list. */\nexport interface SpeedState {\n  /** Explicit session speed, or the subagent's model default when supplied. */\n  tier: SpeedTier\n  /** Codex model ids whose catalog advertises a fast tier. */\n  fastModels: string[]\n}\n\n/** Session overrides plus persisted subagent model defaults. */\nexport interface SpeedController {\n  /** Pass the current Codex model to resolve a subagent's default speed. */\n  speed(sessionId: string, model?: string): Promise<SpeedState>\n  /** Set one session's speed tier. */\n  setSpeed(sessionId: string, tier: SpeedTier): Promise<void>\n}\n\n/** One logged-in account, as rendered by the Settings page. */\nexport interface AccountStatus {\n  /** Stable account key (store identity). */\n  key: string\n  /** Display identity (email / login), when known. */\n  account?: string\n  /** Epoch milliseconds at which the stored access token expires. */\n  expiresAt?: number\n  /** Plan name the session carries (codex planType / claude subscriptionType), when known. */\n  plan?: string\n  /** Whether direct (non-pool) routes serve this account. */\n  isDefault: boolean\n}\n\n/** Login state of one provider, as rendered by the Settings page. */\nexport interface ProviderStatus {\n  displayName?: string\n  /** Whether a login attempt is currently waiting for its code. */\n  busy: boolean\n  /** Logged-in accounts, default first. */\n  accounts: AccountStatus[]\n  /** The last login error, shown until the next success. */\n  detail?: string\n  /** The CLI version this route presents (Codex, Claude), and where it came from. */\n  clientVersion?: CliVersion\n}\n\n/** How a Claude login should acquire credentials (other providers ignore it). */\nexport type LoginMethod = 'oauth' | 'keychain'\n\n/** Proxy config operations behind the `proxyGet/proxySet/proxyTest` endpoints. */\nexport interface ProxyConfigController {\n  /** Current proxy configuration (secrets omitted). */\n  get(): Promise<ProxyConfigView>\n  /** Validate, persist, and apply one config. */\n  set(input: ProxyInput): Promise<ProxyConfigView>\n  /** Probe one destination through the draft (unsaved) or stored proxy. */\n  test(payload: { url?: string; proxy?: ProxyDraft }): Promise<ProxyTestResult>\n}\n\n/** One model's default-effort picker state, as rendered by the Settings page. */\nexport interface ModelDefaultView {\n  /** Wire model id. */\n  id: string\n  /** Human-readable display name. */\n  name: string\n  /** Advertised effort levels, in catalog order (empty when the model has no reasoning). */\n  efforts: { id: string; name: string }[]\n  /** The user-configured default effort, when set. */\n  configured?: string\n}\n\n/** One provider's default-effort picker state. */\nexport interface ModelDefaultsCatalog {\n  /** The subscription provider route. */\n  provider: ProviderId\n  /** Models the picker can configure, in catalog order. */\n  models: ModelDefaultView[]\n}\n\n/** Per-account catalog returned by providerSettings, including providers without usage APIs. */\nexport interface ProviderAccountCatalog {\n  key: string\n  /** Original identity; the editable alias lives in settings.accounts[key].alias. */\n  label: string\n  models: { id: string; name: string }[]\n  unavailable?: boolean\n}\n\n/** Provider and account preference operations behind providerSettings/setProviderSettings. */\nexport interface ProviderSettingsController {\n  /** Local preferences only: status must not fetch a model catalog. */\n  displayName?(provider: ProviderId): string | undefined\n  get(provider: ProviderId, force: boolean): Promise<unknown>\n  set(provider: ProviderId, settings: unknown): Promise<void>\n}\n\nexport interface ModelDefaultsController {\n  /** Per-provider picker state for the Settings page. */\n  catalog(force?: boolean): Promise<ModelDefaultsCatalog[]>\n  /** Set one model's configured default effort; undefined clears the override. */\n  set(provider: ProviderId, model: string, effort: string | undefined): Promise<void>\n}\n\n/** Provider-agnostic auth operations the RPC handler delegates to. */\nexport interface AuthController {\n  prepareReset?(account: string, signal: AbortSignal): Promise<unknown>\n  consumeReset?(account: string, ticket: string, signal: AbortSignal): Promise<void>\n  /** Current status of one provider. */\n  status(provider: ProviderId): Promise<ProviderStatus>\n  /**\n   * Start a background login attempt.\n   * @param provider - the provider route.\n   * @param method - Claude only: force the OAuth browser flow or the Claude\n   *   Code credential import; omitted keeps the auto behavior (import when\n   *   available, else OAuth).\n   * @returns the authorize URL for the user's browser; device-flow providers\n   *   (copilot) also return the `userCode` the user types at that URL.\n   * @throws when an attempt is already running for this provider.\n   */\n  login(provider: ProviderId, method?: LoginMethod): Promise<{ authorizeUrl: string; userCode?: string }>\n  /**\n   * Feed a pasted callback URL or bare code into the pending attempt.\n   * @throws when no attempt is pending or the input is unusable.\n   */\n  manual(provider: ProviderId, input: string): Promise<void>\n  /** Abort the pending attempt; a no-op when none is pending. */\n  cancel(provider: ProviderId): Promise<void>\n  /** Delete one account's stored session. */\n  logout(provider: ProviderId, account: string): Promise<void>\n  /** Pin the account direct (non-pool) routes serve. */\n  setDefault(provider: ProviderId, account: string): Promise<void>\n  /**\n   * Current subscription usage of one account.\n   * @param signal - caller cancellation from the RPC transport.\n   * @param force - bypass a fresh cached snapshot for an honest re-check\n   *   (the manual Refresh button); a live failure cooldown still applies.\n   * @returns `{ supported: false }` when the provider has no usage endpoint.\n   * @throws when logged out or the usage lookup fails.\n   */\n  usage(provider: ProviderId, account: string, signal: AbortSignal, force?: boolean): Promise<ProviderUsage>\n  /**\n   * Read one image attachment's bytes for inline display.\n   * @param ref - the full durable reference (`readImage` verifies against it).\n   * @param signal - caller cancellation from the RPC transport.\n   * @returns the media type and base64-encoded bytes.\n   * @throws when no attachment service is mounted or the read fails.\n   */\n  readImage(ref: ImageAttachmentRef, signal: AbortSignal): Promise<ImageBytesResult>\n  /**\n   * Read one generated video's bytes for inline playback.\n   * @param name - bare MP4 file name inside the plugin's videos directory\n   *   (validated against {@link VIDEO_NAME_PATTERN}; never a path).\n   * @param signal - caller cancellation from the RPC transport.\n   * @returns the media type and base64-encoded bytes.\n   * @throws when the file does not exist or cannot be read.\n   */\n  readVideo(name: string, signal: AbortSignal): Promise<VideoBytesResult>\n}\n\n/** Payload carried no usable provider id — an RPC client bug, not a server failure. */\nexport class BadRequest extends Error {}\n\n/**\n * Structural face of `connection.fetch.register` shared by both dsh lines.\n * The 0.1.2-alpha typings list only `GET`/`HEAD` methods and no\n * `requestBody`, while the 0.1.5 line adds `POST` plus the body mode; the\n * runtime on both lines dispatches any declared method to the exact route,\n * so the route is typed here rather than against either line's declaration.\n */\ninterface FetchRouteCompat {\n  readonly path: string\n  readonly methods: readonly ('GET' | 'HEAD' | 'POST')[]\n  /** Buffered: the bridge aggregates the JSON body before `fetch` runs (0.1.5+; ignored earlier). */\n  readonly requestBody: 'buffered'\n  readonly fetch: (request: Request) => Promise<Response>\n}\n\ntype FetchRegisterCompat = (route: FetchRouteCompat) => () => Promise<void>\n\n/** Connection `client-request` envelope, as the browser rpc caller sends it. */\ninterface ClientRequestEnvelope {\n  type: 'client-request'\n  rpcId: string\n  method: string\n  payload: unknown\n}\n\nfunction readEnvelope(body: unknown): ClientRequestEnvelope | undefined {\n  if (typeof body !== 'object' || body === null) return undefined\n  const record = body as Record<string, unknown>\n  if (record.type !== 'client-request' || typeof record.rpcId !== 'string' || typeof record.method !== 'string') return undefined\n  return { type: 'client-request', rpcId: record.rpcId, method: record.method, payload: record.payload }\n}\n\nfunction serverResponse(rpcId: string, result: RpcResult<unknown>): Response {\n  return Response.json({ type: 'server-response', rpcId, result })\n}\n\n/**\n * Wrap one endpoint's RPC handler as an exact Fetch route: decode the\n * `client-request` envelope the browser rpc caller posts, run the handler,\n * and answer with the matching `server-response` envelope — the same wire\n * contract the dedicated-channel bridge used to apply, reproduced here so\n * `rpc.call('/api', 'subscriptions-auth.<endpoint>', payload)` keeps working\n * unchanged on the browser side.\n */\nfunction fetchRouteFor(endpoint: string, handler: SubscriptionsRpcHandler): FetchRouteCompat {\n  const method = `${SUBSCRIPTIONS_AUTH_PREFIX}${endpoint}`\n  return {\n    path: `/api/${method}`,\n    methods: ['POST'],\n    requestBody: 'buffered',\n    fetch: async (request) => {\n      if (request.headers.get('content-type')?.split(';', 1)[0]?.trim().toLowerCase() !== 'application/json') {\n        return new Response('content type must be application/json', { status: 415 })\n      }\n      let body: unknown\n      try {\n        body = await request.json()\n      } catch {\n        return new Response('body is not JSON', { status: 400 })\n      }\n      const envelope = readEnvelope(body)\n      if (envelope === undefined) {\n        const rawId = (body as Record<string, unknown> | null)?.rpcId\n        return serverResponse(typeof rawId === 'string' ? rawId : 'invalid-request', {\n          ok: false,\n          error: { code: 'gateway/bad-request', message: 'invalid client-request message', details: { issues: [] } },\n        })\n      }\n      if (envelope.method !== method) {\n        return serverResponse(envelope.rpcId, {\n          ok: false,\n          error: {\n            code: 'gateway/bad-request',\n            message: `method ${JSON.stringify(envelope.method)} does not match endpoint ${JSON.stringify(method)}`,\n            details: { issues: [] },\n          },\n        })\n      }\n      return serverResponse(envelope.rpcId, await handler(endpoint, envelope.payload, request.signal))\n    },\n  }\n}\n\nfunction ok(value: unknown): RpcResult<unknown> {\n  return { ok: true, value }\n}\n\nfunction failure(error: unknown): RpcResult<unknown> {\n  const message = error instanceof Error ? error.message : String(error)\n  if (error instanceof BadRequest) {\n    // The issues array is zod-shaped upstream; this channel validates by hand.\n    return { ok: false, error: { code: 'bad-request', message, details: { issues: [] } } }\n  }\n  return { ok: false, error: { code: 'internal', message, details: {} } }\n}\n\nfunction readProvider(payload: unknown): ProviderId {\n  if (typeof payload !== 'object' || payload === null) throw new BadRequest('payload must be an object')\n  const provider = (payload as Record<string, unknown>).provider\n  if (typeof provider !== 'string' || !(PROVIDER_IDS as readonly string[]).includes(provider)) {\n    throw new BadRequest(`payload.provider must be one of ${PROVIDER_IDS.join(', ')}`)\n  }\n  return provider as ProviderId\n}\n\nfunction readString(payload: unknown, field: string): string {\n  const value = (payload as Record<string, unknown>)[field]\n  if (typeof value !== 'string' || value.length === 0) {\n    throw new BadRequest(`payload.${field} must be a non-empty string`)\n  }\n  return value\n}\n\n/** Validate the `setModelDefault` endpoint's payload. */\nfunction readModelDefaultInput(payload: unknown): { provider: ProviderId; model: string; effort?: string } {\n  const provider = readProvider(payload)\n  const model = readString(payload, 'model')\n  const record = payload as Record<string, unknown>\n  let effort: string | undefined\n  if (record.effort !== undefined) {\n    if (typeof record.effort !== 'string' || record.effort.length === 0) {\n      throw new BadRequest('payload.effort must be a non-empty string when present')\n    }\n    effort = record.effort\n  }\n  return {\n    provider,\n    model,\n    ...(effort === undefined ? {} : { effort }),\n  }\n}\n\n/** Validate the optional Claude login method. */\nfunction readLoginMethod(payload: unknown, provider: ProviderId): LoginMethod | undefined {\n  const method = (payload as Record<string, unknown>).method\n  if (method === undefined) return undefined\n  if (provider !== 'claude') throw new BadRequest('payload.method is only valid for claude')\n  if (method !== 'oauth' && method !== 'keychain') {\n    throw new BadRequest('payload.method must be \"oauth\" or \"keychain\"')\n  }\n  return method\n}\n\n/** Validate the `setSpeed` endpoint's tier. */\nfunction readSpeedTier(payload: unknown): SpeedTier {\n  const tier = (payload as Record<string, unknown>).tier\n  if (tier !== 'standard' && tier !== 'fast') {\n    throw new BadRequest('payload.tier must be \"standard\" or \"fast\"')\n  }\n  return tier\n}\n\n/** Validate the `image` endpoint's payload into a full attachment reference. */\nfunction readImageRef(payload: unknown): ImageAttachmentRef {\n  if (typeof payload !== 'object' || payload === null) throw new BadRequest('payload must be an object')\n  const record = payload as Record<string, unknown>\n  const attachmentId = record.attachmentId\n  if (typeof attachmentId !== 'string' || attachmentId.length === 0) {\n    throw new BadRequest('payload.attachmentId must be a non-empty string')\n  }\n  const mediaType = record.mediaType\n  if (typeof mediaType !== 'string' || !(IMAGE_MEDIA_TYPES as readonly string[]).includes(mediaType)) {\n    throw new BadRequest(`payload.mediaType must be one of ${IMAGE_MEDIA_TYPES.join(', ')}`)\n  }\n  for (const field of ['bytes', 'width', 'height'] as const) {\n    const value = record[field]\n    if (typeof value !== 'number' || !Number.isInteger(value) || value <= 0) {\n      throw new BadRequest(`payload.${field} must be a positive integer`)\n    }\n  }\n  const name = record.name\n  if (name !== undefined && typeof name !== 'string') {\n    throw new BadRequest('payload.name must be a string when present')\n  }\n  return {\n    attachmentId: AttachmentId(attachmentId),\n    mediaType: mediaType as ImageAttachmentRef['mediaType'],\n    bytes: record.bytes as number,\n    width: record.width as number,\n    height: record.height as number,\n    ...name === undefined ? {} : { name: name as string },\n  }\n}\n\n/**\n * Validate the `video` endpoint's payload into a bare file name. Rejecting\n * anything with a path separator (the pattern allows none) pins every read\n * inside the plugin's videos directory.\n */\nfunction readVideoName(payload: unknown): string {\n  if (typeof payload !== 'object' || payload === null) throw new BadRequest('payload must be an object')\n  const name = (payload as Record<string, unknown>).name\n  if (typeof name !== 'string' || !VIDEO_NAME_PATTERN.test(name)) {\n    throw new BadRequest('payload.name must be a bare .mp4 file name')\n  }\n  return name\n}\n\n/** Validate the usage/model catalog endpoints' optional force flag. */\nfunction readForce(payload: unknown): boolean {\n  if (typeof payload !== 'object' || payload === null) return false\n  const force = (payload as Record<string, unknown>).force\n  if (force === undefined) return false\n  if (typeof force !== 'boolean') throw new BadRequest('payload.force must be a boolean when present')\n  return force\n}\n\n/** Validate the session id both speed endpoints carry. */\nfunction readSessionId(payload: unknown): string {\n  if (typeof payload !== 'object' || payload === null) throw new BadRequest('payload must be an object')\n  return readString(payload, 'sessionId')\n}\n\n/** Validate a `proxySet` payload into a shape `ProxyInput` accepts. */\nfunction readProxyInput(payload: unknown): ProxyInput {\n  if (typeof payload !== 'object' || payload === null) throw new BadRequest('payload must be an object')\n  const record = payload as Record<string, unknown>\n  if (typeof record.enabled !== 'boolean') throw new BadRequest('payload.enabled must be a boolean')\n  if (typeof record.url !== 'string') throw new BadRequest('payload.url must be a string')\n  let username: string | undefined\n  if (record.username !== undefined) {\n    if (typeof record.username !== 'string') throw new BadRequest('payload.username must be a string when present')\n    username = record.username\n  }\n  let password: string | null | undefined\n  if (record.password !== undefined) {\n    if (record.password !== null && typeof record.password !== 'string') {\n      throw new BadRequest('payload.password must be a string or null when present')\n    }\n    password = record.password\n  }\n  let bypass: string[] | undefined\n  if (record.bypass !== undefined) {\n    if (!Array.isArray(record.bypass) || record.bypass.some(entry => typeof entry !== 'string')) {\n      throw new BadRequest('payload.bypass must be an array of strings when present')\n    }\n    bypass = record.bypass\n  }\n  return {\n    enabled: record.enabled,\n    url: record.url,\n    ...username === undefined ? {} : { username },\n    ...password === undefined ? {} : { password },\n    ...bypass === undefined ? {} : { bypass },\n  }\n}\n\n/** Validate a `proxyTest` payload (the destination URL and an optional draft). */\nfunction readProxyTestPayload(payload: unknown): { url?: string; proxy?: ProxyDraft } {\n  if (typeof payload !== 'object' || payload === null) return {}\n  const record = payload as Record<string, unknown>\n  const url = record.url\n  if (url === undefined && record.proxy === undefined) return {}\n  if (url !== undefined && (typeof url !== 'string' || url.length === 0)) {\n    throw new BadRequest('payload.url must be a non-empty string when present')\n  }\n  let proxy: ProxyDraft | undefined\n  if (record.proxy !== undefined) {\n    if (typeof record.proxy !== 'object' || record.proxy === null) {\n      throw new BadRequest('payload.proxy must be an object when present')\n    }\n    const draftRecord = record.proxy as Record<string, unknown>\n    if (typeof draftRecord.url !== 'string' || draftRecord.url.length === 0) {\n      throw new BadRequest('payload.proxy.url must be a non-empty string')\n    }\n    let username: string | undefined\n    if (draftRecord.username !== undefined) {\n      if (typeof draftRecord.username !== 'string') {\n        throw new BadRequest('payload.proxy.username must be a string when present')\n      }\n      username = draftRecord.username\n    }\n    let password: string | undefined\n    if (draftRecord.password !== undefined) {\n      if (typeof draftRecord.password !== 'string') {\n        throw new BadRequest('payload.proxy.password must be a string when present')\n      }\n      password = draftRecord.password\n    }\n    proxy = {\n      url: draftRecord.url,\n      ...username === undefined ? {} : { username },\n      ...password === undefined ? {} : { password },\n    }\n  }\n  return {\n    ...url === undefined ? {} : { url },\n    ...proxy === undefined ? {} : { proxy },\n  }\n}\n\nasync function dispatch(\n  controller: AuthController,\n  speed: SpeedController,\n  proxy: ProxyConfigController | undefined,\n  modelDefaults: ModelDefaultsController | undefined,\n  endpoint: string,\n  payload: unknown,\n  signal: AbortSignal,\n  providerSettings?: ProviderSettingsController,\n): Promise<RpcResult<unknown>> {\n  switch (endpoint) {\n    case 'providerSettings':\n      if (!providerSettings) throw new BadRequest('provider settings are unavailable')\n      return ok(await providerSettings.get(readProvider(payload), readForce(payload)))\n    case 'setProviderSettings': {\n      if (!providerSettings) throw new BadRequest('provider settings are unavailable')\n      const provider = readProvider(payload)\n      await providerSettings.set(provider, (payload as Record<string, unknown>).settings)\n      return ok({ ok: true })\n    }\n    case 'status': {\n      // One provider's failure (a corrupt store entry, a broken flow) must not\n      // blind the whole page: it degrades to an error detail on that provider\n      // while the others still report their real status.\n      const entries = await Promise.all(PROVIDER_IDS.map(\n        async provider => [provider, await controller.status(provider).catch((error: unknown) => ({\n          busy: false,\n          accounts: [],\n          detail: error instanceof Error ? error.message : String(error),\n        }) satisfies ProviderStatus)] as const,\n      ))\n      return ok({ providers: Object.fromEntries(entries.map(([provider, status]) => {\n        const displayName = providerSettings?.displayName?.(provider)\n        return [provider, { ...status, ...(displayName ? { displayName } : {}) }]\n      })) })\n    }\n    case 'login': {\n      const provider = readProvider(payload)\n      return ok(await controller.login(provider, readLoginMethod(payload, provider)))\n    }\n    case 'manual': {\n      const provider = readProvider(payload)\n      await controller.manual(provider, readString(payload, 'input'))\n      return ok({ ok: true })\n    }\n    case 'cancel':\n      await controller.cancel(readProvider(payload))\n      return ok({ ok: true })\n    case 'logout': {\n      const provider = readProvider(payload)\n      await controller.logout(provider, readString(payload, 'account'))\n      return ok({ ok: true })\n    }\n    case 'setDefault': {\n      const provider = readProvider(payload)\n      await controller.setDefault(provider, readString(payload, 'account'))\n      return ok({ ok: true })\n    }\n    case 'usage': {\n      const provider = readProvider(payload)\n      return ok(await controller.usage(provider, readString(payload, 'account'), signal, readForce(payload)))\n    }\n    case 'prepareReset':\n      if (!controller.prepareReset) throw new BadRequest('Reset redemption unavailable')\n      return ok(await controller.prepareReset(readString(payload, 'account'), signal))\n    case 'consumeReset':\n      if (!controller.consumeReset) throw new BadRequest('Reset redemption unavailable')\n      await controller.consumeReset(readString(payload, 'account'), readString(payload, 'ticket'), signal)\n      return ok({ ok: true })\n    case 'image':\n      return ok(await controller.readImage(readImageRef(payload), signal))\n    case 'video':\n      return ok(await controller.readVideo(readVideoName(payload), signal))\n    case 'speed':\n      return ok(await speed.speed(readSessionId(payload),\n        (payload as Record<string, unknown>).model === undefined ? undefined : readString(payload, 'model')))\n    case 'setSpeed':\n      await speed.setSpeed(readSessionId(payload), readSpeedTier(payload))\n      return ok({ ok: true })\n    case 'proxyGet':\n      if (proxy === undefined) throw new BadRequest('proxy configuration is unavailable')\n      return ok(await proxy.get())\n    case 'proxySet':\n      if (proxy === undefined) throw new BadRequest('proxy configuration is unavailable')\n      return ok(await proxy.set(readProxyInput(payload)))\n    case 'proxyTest':\n      if (proxy === undefined) throw new BadRequest('proxy configuration is unavailable')\n      return ok(await proxy.test(readProxyTestPayload(payload)))\n    case 'modelDefaults': {\n      if (modelDefaults === undefined) throw new BadRequest('model defaults are unavailable')\n      return ok(await modelDefaults.catalog(readForce(payload)))\n    }\n    case 'setModelDefault':\n      if (modelDefaults === undefined) throw new BadRequest('model defaults are unavailable')\n      {\n        const input = readModelDefaultInput(payload)\n        await modelDefaults.set(input.provider, input.model, input.effort)\n      }\n      return ok({ ok: true })\n    default:\n      throw new BadRequest(`unknown /subscriptions-auth endpoint \"${endpoint}\"`)\n  }\n}\n\n/**\n * Register the `/subscriptions-auth` RPC channel when a host connection exists.\n * @param ctx - the plugin context (headless profiles have no `connection`).\n * @param controller - the auth operations backing the endpoints.\n * @param speed - the per-session speed-tier state backing the Speed toggle.\n * @param proxy - optional proxy-config controller backing `proxyGet`/`proxySet`/`proxyTest`.\n * @param modelDefaults - optional per-model default-effort state backing `modelDefaults`/`setModelDefault`.\n */\nexport function registerAuthRpc(\n  ctx: Context,\n  controller: AuthController,\n  speed: SpeedController,\n  proxy: ProxyConfigController | undefined = undefined,\n  modelDefaults: ModelDefaultsController | undefined = undefined,\n  providerSettings: ProviderSettingsController | undefined = undefined,\n): void {\n  // `connection` is not in this plugin's inject list (headless compositions\n  // lack it), so its startup order is unconstrained: defer registration until\n  // the service exists instead of probing once at apply time.\n  //\n  // Exact Fetch routes under `/api` rather than a dedicated `rpc.handle`\n  // channel: since dsh 0.1.5 the connection plugin no longer injects\n  // `webServer` itself, and `rpc.handle` resolves `webServer` through the\n  // connection plugin's own fiber, so every dedicated channel registration\n  // throws `cannot get property \"webServer\" without inject`. The `/api`\n  // route is mounted by the connection plugin (with its own webServer scope)\n  // and applies the same trust fence and browser authentication, so exact\n  // routes below it work on both dsh lines.\n  ctx.inject(['connection'], (ctx) => {\n    const connection = ctx.get('connection') as HostConnectionHandle\n    const handler: SubscriptionsRpcHandler = async (endpoint, payload, signal) => {\n      try {\n        return await dispatch(controller, speed, proxy, modelDefaults, endpoint, payload, signal, providerSettings)\n      } catch (error) {\n        return failure(error)\n      }\n    }\n    const register = connection.fetch.register as unknown as FetchRegisterCompat\n    for (const endpoint of SUBSCRIPTIONS_AUTH_ENDPOINTS) {\n      ctx.effect(\n        () => register(fetchRouteFor(endpoint, handler)),\n        `dsh-plugin-subscriptions: /api/${SUBSCRIPTIONS_AUTH_PREFIX}${endpoint} route`,\n      )\n    }\n  })\n}\n"
    },
    {
      "path": "src/providers/pool.ts",
      "content": "/**\n * The pool adapter: same-subscription account routing, plus optional\n * configured tier extras. The picker is the union of every account's\n * catalog. A model listed by several accounts failovers; a model listed by\n * one account is pinned to it. Tiers are extra picker rows. Member\n * selection is sticky per session (so prompt caches survive) and optionally\n * quota-aware; failures fail over to the next member as long as no stream\n * content chunk has been emitted (leading usage remains buffered).\n */\n\nimport {\n  EMPTY_RESPONSE_CODE,\n  LlmAdapter,\n  LlmError,\n  QUOTA_EXCEEDED_CODE,\n} from '@deepseek-ai/dsh-llm'\nimport type {\n  GenerateOptions,\n  LlmModelInfo,\n  LlmResolvedModelInfo,\n  PreparedAdapterCall,\n  StreamChunk,\n} from '@deepseek-ai/dsh-llm'\nimport type { ProviderId } from '../auth/store.js'\nimport type { AccountAwareAdapter } from './accounts.js'\nimport type { ConcretePoolMember, PoolDefinition, PoolMemberRef } from './pool-family.js'\nimport { poolKey } from './pool-family.js'\nimport { accountKey, classifyPoolFailure, memberKey, PoolHealthRegistry } from './pool-health.js'\nimport type { MemberQuota, PoolUsageTracker } from './pool-usage.js'\nimport { withAbortSignal } from './common.js'\nimport { streamAccountWithReplay } from './replay.js'\n\n/** Member-selection strategy: plain priority failover or quota-aware scheduling. */\nexport type PoolStrategy = 'priority' | 'quota_aware'\n\nexport interface PoolAdapterOptions {\n  /** The live subscription adapters, by provider route. */\n  adapters: Partial<Record<ProviderId, AccountAwareAdapter>>\n  health: PoolHealthRegistry\n  usage: PoolUsageTracker\n  strategy: PoolStrategy\n  /** A challenger must out-urgency the sticky member by this factor to take over. */\n  switchMargin: number\n  /** The default account of one provider (for config members omitting `account`). */\n  defaultAccount: (provider: ProviderId) => Promise<string | undefined>\n  /** Resolve legacy account aliases before pool deduplication and cache identity. */\n  resolveAccount?: (provider: ProviderId, account: string) => Promise<string>\n  /** Account pools (auto-aggregated plus config overrides), resolved lazily. */\n  families: () => Promise<Map<string, PoolDefinition>>\n  /** User-configured extra picker entries (heterogeneous fallbacks), by pool id. */\n  tiers: Record<string, PoolMemberRef[]>\n  onWarn: (message: string) => void\n}\n\n/** Bound on sticky-session memory; oldest entries evict past it. */\nconst STICKY_SESSION_LIMIT = 1000\n\n/** Display form of one member (account shown when pinned). */\nfunction memberLabel(member: PoolMemberRef): string {\n  return member.account === undefined\n    ? `${member.provider}/${member.model}`\n    : `${member.provider}/${member.account}/${member.model}`\n}\n\n/** How long a pools snapshot is trusted (auth changes invalidate immediately). */\nconst POOLS_CACHE_TTL_MS = 5_000\n\nexport class PoolAdapter extends LlmAdapter {\n  /** sessionId|poolId → member key of the last member that served a chunk. */\n  private readonly sticky = new Map<string, string>()\n  /** Messages already warned about — configuration diagnostics repeat every request otherwise. */\n  private readonly warned = new Set<string>()\n  /**\n   * Short-lived pools snapshot. `owns()` runs on every resolveModel — the\n   * model picker issues one per entry — and pool assembly touches every\n   * provider's catalog and account store, so recompute at most this often.\n   * Auth changes bump {@link generation} so a stale snapshot cannot land.\n   */\n  private poolsCache: { at: number; pools: Map<string, PoolDefinition> } | undefined\n  private poolsInflight: Promise<Map<string, PoolDefinition>> | undefined\n  private generation = 0\n\n  constructor(private readonly options: PoolAdapterOptions) {\n    super()\n  }\n\n  /** Drop the pools snapshot so the next read reflects the current accounts. */\n  invalidate(): void {\n    this.generation += 1\n    this.poolsCache = undefined\n    this.poolsInflight = undefined\n  }\n\n  /** Warn once per distinct message (pools() runs on every request). */\n  private warnOnce(message: string): void {\n    if (this.warned.has(message)) return\n    this.warned.add(message)\n    this.options.onWarn(message)\n  }\n\n  /** Drop members whose adapter is not registered (copy — caller state is shared). */\n  private usable(pools: Map<string, PoolDefinition>): Map<string, PoolDefinition> {\n    const result = new Map<string, PoolDefinition>(pools)\n    for (const [id, definition] of [...result]) {\n      const kept = definition.members.filter(member => this.options.adapters[member.provider] !== undefined)\n      if (kept.length === 0) result.delete(id)\n      else if (kept.length < definition.members.length) result.set(id, { ...definition, members: kept })\n    }\n    return result\n  }\n\n  /** Account pools (auto-aggregated plus config overrides) with usable members. */\n  private async familyPools(): Promise<Map<string, PoolDefinition>> {\n    return this.usable(new Map<string, PoolDefinition>(await this.options.families()))\n  }\n\n  /** All pools (account pools merged with extra tiers) with usable members. */\n  private async pools(): Promise<Map<string, PoolDefinition>> {\n    const cached = this.poolsCache\n    if (cached !== undefined && Date.now() - cached.at < POOLS_CACHE_TTL_MS) return cached.pools\n    const gen = this.generation\n    this.poolsInflight ??= this.assemblePools()\n      .then((pools) => {\n        if (this.generation === gen) this.poolsCache = { at: Date.now(), pools }\n        return pools\n      })\n      .finally(() => {\n        this.poolsInflight = undefined\n      })\n    return this.poolsInflight\n  }\n\n  /** Recompute the pools snapshot (account pools merged with extra tiers). */\n  private async assemblePools(): Promise<Map<string, PoolDefinition>> {\n    const pools = await this.familyPools()\n    for (const [id, members] of Object.entries(this.options.tiers)) {\n      if (members.length === 0) continue\n      const owner = members[0].provider\n      const key = poolKey(owner, id)\n      if (pools.has(key)) this.warnOnce(`tier pool \"${id}\" overrides the account pool of the same id under ${owner}`)\n      pools.set(key, { members, extra: true })\n    }\n    return this.usable(pools)\n  }\n\n  /**\n   * Extra picker rows one provider lists (configured tiers). Account pools\n   * reuse the catalog entry of the same wire id, so they are not listed\n   * again — the picker stays one row per model in ChatGPT / Claude / ….\n   */\n  async modelsForProvider(provider: ProviderId): Promise<LlmModelInfo[]> {\n    const pools = await this.pools()\n    const models: LlmModelInfo[] = []\n    for (const [key, definition] of pools) {\n      if (definition.extra !== true) continue\n      if (!key.startsWith(`${provider}/`)) continue\n      const id = key.slice(provider.length + 1)\n      models.push({\n        provider,\n        id,\n        name: definition.name ?? id,\n        ...definition.description === undefined ? {} : { description: definition.description },\n      })\n    }\n    return models\n  }\n\n  /**\n   * Whether `model` on `provider`'s route is served here (several accounts\n   * fail over, one account is pinned, or a configured tier).\n   */\n  async owns(provider: ProviderId, model: string): Promise<boolean> {\n    return (await this.pools()).has(poolKey(provider, model))\n  }\n\n  /**\n   * Resolve every member's account (config members may omit it to mean \"the\n   * default account\") and drop members with no resolvable login. Duplicates\n   * collapse — an explicitly pinned account and the default may coincide.\n   */\n  private async concrete(members: readonly PoolMemberRef[]): Promise<ConcretePoolMember[]> {\n    const seen = new Set<string>()\n    const resolved: ConcretePoolMember[] = []\n    for (const member of members) {\n      const requested = member.account ?? await this.options.defaultAccount(member.provider)\n      if (requested === undefined) continue\n      const account = await (this.options.resolveAccount?.(member.provider, requested) ?? Promise.resolve(requested))\n      const key = memberKey(member.provider, account, member.model)\n      if (seen.has(key)) continue\n      seen.add(key)\n      resolved.push({ provider: member.provider, account, model: member.model })\n    }\n    return resolved\n  }\n\n  /**\n   * Resolve a pool model to the conservative INTERSECTION of its members'\n   * capabilities: the smallest context window and output cap, the reasoning\n   * efforts every member supports, and the modalities all of them accept —\n   * so a request valid for the pool stays valid after a failover. Capability\n   * metadata is account-specific, so every distinct member is resolved.\n   */\n  override async resolveModel(provider: string, model: string, signal?: AbortSignal): Promise<LlmResolvedModelInfo> {\n    return (await this.prepareCall(provider, model, signal)).model\n  }\n\n  override async prepareCall(provider: string, model: string, signal?: AbortSignal): Promise<PreparedAdapterCall> {\n    const definition = (await withAbortSignal(() => this.pools(), signal)).get(poolKey(provider, model))\n    if (definition === undefined) throw new LlmError(`unknown pool model \"${model}\"`, 'NO_ADAPTER')\n    const resolved: LlmResolvedModelInfo[] = []\n    let lastFailure: unknown\n    const members = await withAbortSignal(() => this.concrete(definition.members), signal)\n    const eligible: ConcretePoolMember[] = []\n    for (const member of members) {\n      const adapter = this.options.adapters[member.provider]\n      if (adapter === undefined) continue\n      // Tolerate per-member failures (a misconfigured tier member, a\n      // logged-out provider throwing AUTH): the pool serves as long as ONE\n      // member resolves, mirroring stream()'s failover semantics.\n      try {\n        resolved.push(await withAbortSignal(() => adapter.resolveOwnModel(member.provider, member.model, member.account), signal))\n        eligible.push(member)\n      } catch (error: unknown) {\n        signal?.throwIfAborted()\n        lastFailure = error\n        this.warnOnce(\n          `pool \"${model}\": member ${memberLabel(member)} failed to resolve`\n          + ` (${error instanceof Error ? error.message : String(error)}); excluding it`,\n        )\n      }\n    }\n    if (resolved.length === 0) {\n      throw new LlmError(`pool \"${model}\" has no usable member`, 'NO_ADAPTER', {\n        ...lastFailure === undefined ? {} : { cause: lastFailure },\n      })\n    }\n    const contextWindows = resolved.map(info => info.context?.contextWindow).filter(isNumber)\n    const maxTokens = resolved.map(info => info.defaultMaxTokens).filter(isNumber)\n    const reasoning = intersectReasoning(resolved)\n    const modalities = intersectModalities(resolved)\n    const info: LlmResolvedModelInfo = {\n      provider,\n      id: model,\n      name: definition.name ?? model,\n      ...definition.description === undefined ? {} : { description: definition.description },\n      ...contextWindows.length > 0 ? { context: { contextWindow: Math.min(...contextWindows) } } : {},\n      ...maxTokens.length > 0 ? { defaultMaxTokens: Math.min(...maxTokens) } : {},\n      ...reasoning === undefined ? {} : { reasoning },\n      ...modalities === undefined ? {} : { inputModalities: modalities },\n    }\n    return { model: info, stream: options => this.streamMembers(options, eligible) }\n  }\n\n  async *stream(options: GenerateOptions): AsyncIterable<StreamChunk> {\n    const definition = (await withAbortSignal(() => this.pools(), options.signal)).get(poolKey(options.provider, options.model))\n    if (definition === undefined) throw new LlmError(`unknown pool model \"${options.model}\"`, 'NO_ADAPTER')\n    const members = await withAbortSignal(() => this.concrete(definition.members), options.signal)\n    yield* this.streamMembers(options, members)\n  }\n\n  private async *streamMembers(options: GenerateOptions, members: ConcretePoolMember[]): AsyncIterable<StreamChunk> {\n    const candidates = await withAbortSignal(() => this.select(options.model, members, options.sessionId), options.signal)\n    if (candidates.length === 0) throw this.exhausted(options.model, members)\n    let lastFailure: MemberFailure | undefined\n    let tried = 0\n    for (const member of candidates) {\n      options.signal?.throwIfAborted()\n      const adapter = this.options.adapters[member.provider]\n      if (adapter === undefined) continue\n      tried += 1\n      const iterator = streamAccountWithReplay(\n        adapter, { ...options, provider: member.provider }, member.account, member.model,\n      )[Symbol.asyncIterator]()\n      let first: IteratorResult<StreamChunk>\n      const leadingUsage: StreamChunk[] = []\n      try {\n        first = await iterator.next()\n        // Usage is metadata, not delivered model content. Empty completions\n        // commonly send usage before their terminal failure.\n        while (!first.done && first.value.type === 'usage') {\n          leadingUsage.push(first.value)\n          first = await iterator.next()\n        }\n        if (first.done === true) {\n          throw new LlmError(`${memberLabel(member)} returned an empty stream`, EMPTY_RESPONSE_CODE)\n        }\n        if (first.value.type === 'finish' && first.value.reason.kind === 'error') {\n          const failure = first.value.reason.failure\n          throw new LlmError(failure.message, failure.code, failure)\n        }\n      } catch (error: unknown) {\n        try { await iterator.return?.() } catch { /* preserve the attempt failure */ }\n        options.signal?.throwIfAborted()\n        const classification = classifyPoolFailure(error, member.provider)\n        if (classification.action === 'throw') throw error\n        if ('cooldownMs' in classification) {\n          this.options.health.markUnavailable(\n            classification.scope === 'account'\n              ? accountKey(member.provider, member.account)\n              : memberKey(member.provider, member.account, member.model),\n            classification.cooldownMs,\n            classification.reason,\n          )\n          // A quota failure invalidates the cached usage snapshot so the NEXT\n          // selection re-polls instead of trusting minutes-old percentages.\n          // Transient/auth failures say nothing about quota — keep the cache.\n          if (classification.reason === QUOTA_EXCEEDED_CODE || classification.reason === 'RATE_LIMIT') {\n            this.options.usage.invalidate(member.provider, member.account)\n          }\n        }\n        this.options.onWarn(\n          `pool \"${options.model}\": ${memberLabel(member)} failed before any output`\n          + ` (${describeFailure(error)}); trying the next member`,\n        )\n        lastFailure = { member, error }\n        continue\n      }\n      this.remember(options.model, options.sessionId, member)\n      // Past the first content chunk there is no clean attempt boundary: whatever\n      // the member does next (including failing) reaches the caller as-is.\n      // The finally closes the member stream when the CALLER walks away\n      // early (break / .return()) — manual iteration does not propagate\n      // closure the way `yield*` would, and a half-consumed member stream\n      // must not linger holding its connection.\n      try {\n        yield* leadingUsage\n        yield first.value\n        for (let next = await iterator.next(); next.done !== true; next = await iterator.next()) {\n          yield next.value\n        }\n      } finally {\n        try {\n          await iterator.return?.()\n        } catch {\n          // Closing a half-consumed member stream must not mask the outcome.\n        }\n      }\n      return\n    }\n    throw this.exhausted(options.model, members, lastFailure, tried)\n  }\n\n  /**\n   * Order the candidates for one request. Health filters both strategies;\n   * `quota_aware` then ranks by urgency (members without telemetry, e.g.\n   * copilot, score zero and sink to the bottom of their class), while\n   * quota-exhausted members stay as a last-resort tail in pool order. The\n   * sticky member keeps its lead unless a challenger out-scores it by\n   * `switchMargin`.\n   */\n  private async select(\n    poolId: string,\n    members: ConcretePoolMember[],\n    sessionId: GenerateOptions['sessionId'],\n  ): Promise<ConcretePoolMember[]> {\n    const usable = members.filter(member =>\n      this.options.adapters[member.provider] !== undefined\n      && this.options.health.isMemberAvailable(member.provider, member.account, member.model))\n    if (usable.length === 0) return []\n    const stickyMember = sessionId === undefined\n      ? undefined\n      : usable.find(member =>\n        memberKey(member.provider, member.account, member.model) === this.sticky.get(stickyKey(poolId, sessionId)))\n    if (this.options.strategy === 'priority') {\n      return stickyMember === undefined\n        ? usable\n        : [stickyMember, ...usable.filter(member => member !== stickyMember)]\n    }\n    const quotas = new Map<ConcretePoolMember, MemberQuota>(\n      await Promise.all(usable.map(async member => [member, await this.options.usage.quotaFor(member)] as const)),\n    )\n    const scored = usable.filter(member => quotas.get(member)?.available === true)\n    const quotaFull = usable.filter(member => quotas.get(member)?.available === false)\n    scored.sort((a, b) => (quotas.get(b)?.urgency ?? 0) - (quotas.get(a)?.urgency ?? 0))\n    if (stickyMember !== undefined && scored.includes(stickyMember)) {\n      const best = scored[0]\n      const stickyUrgency = quotas.get(stickyMember)?.urgency ?? 0\n      const bestUrgency = quotas.get(best)?.urgency ?? 0\n      if (best === stickyMember || bestUrgency <= stickyUrgency * this.options.switchMargin) {\n        // Sticky holds (no challenger beats it by the margin): lead with it.\n        scored.splice(scored.indexOf(stickyMember), 1)\n        scored.unshift(stickyMember)\n      }\n    }\n    return [...scored, ...quotaFull]\n  }\n\n  /** Pin the serving member to the session (with bounded memory). */\n  private remember(poolId: string, sessionId: GenerateOptions['sessionId'], member: ConcretePoolMember): void {\n    if (sessionId === undefined) return\n    const key = stickyKey(poolId, sessionId)\n    this.sticky.delete(key)\n    if (this.sticky.size >= STICKY_SESSION_LIMIT) {\n      const oldest = this.sticky.keys().next()\n      if (oldest.done !== true) this.sticky.delete(oldest.value)\n    }\n    this.sticky.set(key, memberKey(member.provider, member.account, member.model))\n  }\n\n  /**\n   * The error for an exhausted pool. It says WHY (issue #139): the last\n   * member failure of this request when members were tried, or the cooling\n   * record that kept every member out of the candidate set — and its `code`\n   * is that failure's own code, never a synthetic `RATE_LIMIT` (a transport\n   * blip on a single-member pool used to be reported as a rate limit). The\n   * earliest recovery hint is scoped to THIS pool's members (the health\n   * registry is shared across pools).\n   */\n  private exhausted(model: string, pool: ConcretePoolMember[], last?: MemberFailure, tried = 0): LlmError {\n    const keys = new Set<string>()\n    for (const member of pool) {\n      keys.add(memberKey(member.provider, member.account, member.model))\n      keys.add(accountKey(member.provider, member.account))\n    }\n    const now = Date.now()\n    const cooling = this.options.health.earliestRecoveryRecord(keys, now)\n    const retryAfterMs = cooling === undefined ? undefined : Math.max(cooling.unavailableUntil - now, 1)\n    const recovers = retryAfterMs === undefined ? '' : ` recovers in ${formatDuration(retryAfterMs)}`\n    let message: string\n    let code: string\n    if (last !== undefined) {\n      const { member, error } = last\n      code = error instanceof LlmError ? error.code : 'TRANSPORT'\n      message = `pool \"${model}\" exhausted: ${tried} of ${pool.length} member(s) failed;`\n        + ` last ${memberLabel(member)} (${describeFailure(error)})`\n        + (cooling === undefined ? '' : `; earliest member${recovers}`)\n    } else if (cooling !== undefined) {\n      code = cooling.reason\n      message = `pool \"${model}\" exhausted: every member is cooling down;`\n        + ` ${cooling.key} (${cooling.reason})${recovers}`\n    } else {\n      code = 'NO_ADAPTER'\n      message = `pool \"${model}\" exhausted: no usable member`\n    }\n    const failure = last?.error instanceof LlmError ? last.error.failure : undefined\n    this.options.onWarn(message)\n    return new LlmError(message, code, {\n      ...retryAfterMs === undefined ? {} : { providerRetryAfterMs: retryAfterMs },\n      ...failure?.status === undefined ? {} : { status: failure.status },\n      ...failure?.requestId === undefined ? {} : { requestId: failure.requestId },\n      ...last === undefined ? {} : { cause: last.error },\n    })\n  }\n}\n\n/** The member that failed last in one request, with its failure. */\ninterface MemberFailure {\n  member: ConcretePoolMember\n  error: unknown\n}\n\n/** `CODE: message` for an LlmError, the message alone otherwise. */\nfunction describeFailure(error: unknown): string {\n  if (error instanceof LlmError) return `${error.code}: ${error.message}`\n  return error instanceof Error ? error.message : String(error)\n}\n\n/** Compact human duration (`42s`, `4m12s`, `35h00m`). */\nfunction formatDuration(ms: number): string {\n  const total = Math.max(1, Math.round(ms / 1000))\n  const hours = Math.floor(total / 3600)\n  const minutes = Math.floor((total % 3600) / 60)\n  const seconds = total % 60\n  if (hours > 0) return `${hours}h${String(minutes).padStart(2, '0')}m`\n  if (minutes > 0) return `${minutes}m${String(seconds).padStart(2, '0')}s`\n  return `${seconds}s`\n}\n\nfunction stickyKey(poolId: string, sessionId: NonNullable<GenerateOptions['sessionId']>): string {\n  return `${String(sessionId)}|${poolId}`\n}\n\nfunction isNumber(value: number | undefined): value is number {\n  return value !== undefined\n}\n\n/** Reasoning efforts every member supports (id intersection, first member's order). */\nfunction intersectReasoning(\n  resolved: readonly LlmResolvedModelInfo[],\n): LlmResolvedModelInfo['reasoning'] | undefined {\n  const [first, ...rest] = resolved\n  if (first?.reasoning === undefined) return undefined\n  const efforts = first.reasoning.efforts.filter(effort =>\n    rest.every(info => info.reasoning?.efforts.some(other => other.id === effort.id) === true))\n  if (efforts.length === 0) return undefined\n  const defaultEffort = first.reasoning.defaultEffort !== undefined\n    && efforts.some(effort => effort.id === first.reasoning?.defaultEffort)\n    ? first.reasoning.defaultEffort\n    : undefined\n  return { efforts, ...defaultEffort === undefined ? {} : { defaultEffort } }\n}\n\n/** Modalities all members accept; undefined when any member leaves it unknown. */\nfunction intersectModalities(\n  resolved: readonly LlmResolvedModelInfo[],\n): LlmResolvedModelInfo['inputModalities'] | undefined {\n  const [first, ...rest] = resolved\n  if (first?.inputModalities === undefined) return undefined\n  const modalities = first.inputModalities.filter(modality =>\n    rest.every(info => info.inputModalities?.includes(modality) === true))\n  // An empty intersection would declare negative capability (\"accepts\n  // nothing\"); report unknown instead — the serving member enforces its own\n  // limits at request time.\n  return modalities.length === 0 ? undefined : modalities\n}\n"
    },
    {
      "path": "src/providers/replay.ts",
      "content": "import { createHash } from 'node:crypto'\nimport type { GenerateOptions, ReplayEnvelope, StreamChunk } from '@deepseek-ai/dsh-llm'\nimport type { AccountAwareAdapter } from './accounts.js'\n\nconst REPLAY_KIND = 'subscriptions-account-replay'\n\n/** Bind opaque provider replay to the concrete account/model behind a public route alias. */\nexport async function* streamAccountWithReplay(\n  adapter: AccountAwareAdapter,\n  options: GenerateOptions,\n  account: string,\n  model = options.model,\n): AsyncIterable<StreamChunk> {\n  const key = createHash('sha256').update(JSON.stringify([options.provider, account, model])).digest('hex')\n  const messages = options.messages.map(message => {\n    if (message.role !== 'assistant' || message.source?.replayState === undefined) return message\n    const source = message.source\n    if (source.replayState === null || typeof source.replayState !== 'object' || !('response' in source.replayState)) return message\n    const replay = source.replayState as ReplayEnvelope\n    const response = replay.response\n    if (response !== null && typeof response === 'object' && 'kind' in response && response.kind === REPLAY_KIND) {\n      if ('version' in response && response.version === 1 && 'key' in response && response.key === key && 'state' in response) {\n        return { ...message, source: { ...source, provider: options.provider, model, replayState: { ...replay, response: response.state } } }\n      }\n      const { replayState: _discarded, ...withoutReplay } = source\n      return { ...message, source: withoutReplay }\n    }\n    // Unwrapped older histories retain their existing direct-route behavior.\n    // An alias alone cannot identify which concrete member produced old replay.\n    if (source.provider === options.provider && source.model === model) return message\n    const { replayState: _discarded, ...withoutReplay } = source\n    return { ...message, source: withoutReplay }\n  })\n  for await (const chunk of adapter.streamAccount({ ...options, model, messages }, account)) {\n    if (chunk.type === 'finish' && chunk.replayState !== undefined) {\n      yield { ...chunk, replayState: { ...chunk.replayState, response: {\n        kind: REPLAY_KIND, version: 1, key, state: chunk.replayState.response,\n      } } }\n    } else yield chunk\n  }\n}\n"
    },
    {
      "path": "src/providers/image-pool.ts",
      "content": "/** Account scheduling shared by image generation and editing, independent of chat catalogs/quota. */\nimport { LlmError } from '@deepseek-ai/dsh-llm'\nimport type { AccountTokenManager } from './accounts.js'\nimport { httpLlmError } from './common.js'\nimport type { RateLimitResetReader } from './rate-limit.js'\nimport { AUTH_COOLDOWN_MS, DEFAULT_QUOTA_COOLDOWN_MS, TRANSIENT_COOLDOWN_MS, PoolHealthRegistry, memberKey } from './pool-health.js'\n\ntype ImageProvider = 'codex' | 'grok'\ninterface ImageSession { accessToken: string; refreshToken: string; expiresAt: number }\n\nexport interface ImageAccountRequest<S extends ImageSession> {\n  provider: ImageProvider\n  tokens: AccountTokenManager<S>\n  signal: AbortSignal\n  /** Session object identity provides bounded-lifetime affinity, also across generate/edit. */\n  owner?: object | undefined\n  rateLimitReset: RateLimitResetReader\n  send: (session: S) => Promise<Response>\n}\n\nexport class ImageAccountPool {\n  // Deliberately separate from chat health: image quotas/entitlements need not match chat.\n  private readonly health = new PoolHealthRegistry()\n  private sticky = new WeakMap<object, Map<ImageProvider, string>>()\n\n  constructor(private readonly options: { enabled?: boolean; onWarn?: (message: string) => void } = {}) {}\n\n  /** Login/logout clears cooling image members and stale session affinity. */\n  clear(provider: ImageProvider, account?: string): void {\n    this.health.clear(provider, account)\n    this.sticky = new WeakMap()\n  }\n\n  async request<S extends ImageSession>(request: ImageAccountRequest<S>): Promise<Response> {\n    const { provider, tokens, signal, owner, send, rateLimitReset } = request\n    signal.throwIfAborted()\n    const accounts = await tokens.list()\n    if (accounts.length === 0) {\n      await tokens.session() // standard provider-specific login hint\n      throw new LlmError('image_generate: no image account is logged in', 'MISSING_CREDENTIAL')\n    }\n    const pooling = this.options.enabled !== false\n    const members = (pooling ? accounts : accounts.slice(0, 1)).map(entry => entry.key)\n    const sticky = pooling && owner !== undefined ? this.sticky.get(owner)?.get(provider) : undefined\n    const ordered = sticky !== undefined && members.includes(sticky)\n      ? [sticky, ...members.filter(key => key !== sticky)] : members\n    let lastError: unknown\n    for (const account of ordered) {\n      signal.throwIfAborted()\n      const key = memberKey(provider, account, 'images')\n      if (pooling && !this.health.isAvailable(key)) continue\n      let failure: LlmError\n      try {\n        let session = await tokens.session(account)\n        signal.throwIfAborted()\n        let response = await send(session)\n        // Only a definitive unauthorized rejection permits retrying this account.\n        if (response.status === 401) {\n          await response.body?.cancel()\n          session = await tokens.session(account, true)\n          signal.throwIfAborted()\n          response = await send(session)\n        }\n        signal.throwIfAborted()\n        if (response.ok) {\n          if (pooling && owner !== undefined) {\n            let affinity = this.sticky.get(owner)\n            if (affinity === undefined) { affinity = new Map(); this.sticky.set(owner, affinity) }\n            affinity.set(provider, account)\n          }\n          return response\n        }\n        // Images can be produced despite timeouts/server failures. Switch only on\n        // explicit auth/quota/entitlement rejection, never ambiguous transport/5xx.\n        failure = await httpLlmError(response, 'image_generate', { rateLimitReset })\n        if (![401, 402, 403, 404, 429].includes(response.status)) throw failure\n      } catch (error) {\n        signal.throwIfAborted()\n        if (!(error instanceof LlmError) || !['AUTH', 'INVALID_CREDENTIAL', 'MISSING_CREDENTIAL', 'RATE_LIMIT', 'HTTP_402', 'HTTP_404'].includes(error.code)) throw error\n        failure = error\n      }\n      if (!pooling) throw failure\n      const delay = failure.failure.providerRetryAfterMs ?? (failure.code === 'RATE_LIMIT'\n        ? DEFAULT_QUOTA_COOLDOWN_MS\n        : ['AUTH', 'INVALID_CREDENTIAL', 'MISSING_CREDENTIAL'].includes(failure.code) ? AUTH_COOLDOWN_MS : TRANSIENT_COOLDOWN_MS)\n      this.health.markUnavailable(key, delay, failure.code)\n      this.options.onWarn?.(`image pool ${provider}: account ${members.indexOf(account) + 1}/${members.length} rejected (${failure.code}); checking remaining accounts`)\n      lastError = failure\n    }\n    if (lastError !== undefined) throw lastError\n    const recovery = this.health.earliestRecovery(new Set(members.map(account => memberKey(provider, account, 'images'))))\n    throw new LlmError(`image_generate: all ${provider} image accounts are cooling down`, 'RATE_LIMIT', {\n      ...recovery === undefined ? {} : { providerRetryAfterMs: Math.max(0, recovery - Date.now()) },\n    })\n  }\n}\n"
    },
    {
      "path": "src/auth/store.ts",
      "content": "/**\n * On-disk OAuth session store at `~/.dsh/plugins/subscriptions/auth.json`.\n *\n * The file is a JSON object keyed by provider id, each entry holding that\n * provider's ACCOUNTS: a map of account key → session plus the default\n * account's key. Writes are atomic (tmp file + rename) with mode 0600\n * because they carry bearer tokens. Session shapes live here (not in the\n * provider modules) because this file owns the durable format.\n *\n * Backward compatibility: entries written by single-account versions hold\n * the session fields directly (no `accounts` wrapper); reads migrate them\n * in memory, and the next write persists the new shape — existing logins\n * survive the upgrade untouched.\n */\n\nimport { createHash } from 'node:crypto'\nimport { decodeJwtPayload } from './jwt.js'\nimport { chmod, mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises'\nimport { dirname } from 'node:path'\nimport { dshHomePath } from '@deepseek-ai/dsh-home-paths'\n\n/** Provider routes this plugin can serve. */\nexport type ProviderId = 'codex' | 'claude' | 'grok' | 'copilot' | 'antigravity'\n\n/** Every provider route, in display order. */\nexport const PROVIDER_IDS: readonly ProviderId[] = ['codex', 'claude', 'grok', 'copilot', 'antigravity']\n\n/** Stored ChatGPT/Codex subscription session. */\nexport interface CodexSession {\n  accessToken: string\n  refreshToken: string\n  /** Epoch milliseconds at which the access token expires. */\n  expiresAt: number\n  /** `chatgpt_account_id` claim from the id token; sent as the `chatgpt-account-id` header. */\n  accountId: string\n  idToken?: string\n  /** User email from the id token, when the token carried it. */\n  emailAddress?: string\n  /** `chatgpt_plan_type` claim from the id token (e.g. `plus`, `pro`), when present. */\n  planType?: string\n}\n\n/** Stored Claude Pro/Max subscription session. */\nexport interface ClaudeSession {\n  accessToken: string\n  refreshToken: string\n  /** Epoch milliseconds at which the access token expires. */\n  expiresAt: number\n  /** Scope string the tokens were issued with; echoed on refresh. */\n  scopes: string\n  emailAddress?: string\n  subscriptionType?: string\n  /**\n   * True when this account was imported from Claude Code's own credential\n   * store (Keychain/file): only bound accounts sync refreshes back to it.\n   */\n  keychainBound?: boolean\n}\n\n/** Stored Grok (X Premium / xAI) subscription session. */\nexport interface GrokSession {\n  accessToken: string\n  refreshToken: string\n  /** Epoch milliseconds at which the access token expires. */\n  expiresAt: number\n  /** Token endpoint from OIDC discovery; retained for refreshes. */\n  tokenEndpoint: string\n  scopes?: string\n  /** Display account: email, username, or subject claim from the id token. */\n  account?: string\n}\n\n/**\n * Stored GitHub Copilot subscription session. Two token generations are at\n * play: the long-lived GitHub OAuth token from the device flow is kept in\n * `refreshToken`, and `accessToken` carries the short-lived (~30 minutes)\n * Copilot API token exchanged from it. A \"refresh\" is therefore a fresh\n * exchange against `copilot_internal/v2/token`, not an OAuth grant.\n */\nexport interface CopilotSession {\n  /** Copilot API token; sent as the bearer on api.githubcopilot.com. */\n  accessToken: string\n  /** Long-lived GitHub OAuth token from the device flow. */\n  refreshToken: string\n  /** Epoch milliseconds at which the Copilot API token expires. */\n  expiresAt: number\n  /** GitHub login name, for the status display. */\n  account?: string\n}\n\n/** Stored Google OAuth session for the Antigravity v1internal API. */\nexport interface AntigravitySession {\n  accessToken: string\n  refreshToken: string\n  /** Epoch milliseconds at which the Google access token expires. */\n  expiresAt: number\n  /** Cloud AI Companion project required by Antigravity request envelopes. */\n  projectId: string\n  /** Google account email, for the status display. */\n  account?: string\n  /** Subscription tier observed during project discovery. */\n  plan?: string\n  /** Granted Google OAuth scopes, when the token endpoint returned them. */\n  scopes?: string\n}\n\n/** One provider's accounts: account key → session, plus the default account. */\nexport interface ProviderAccounts<S> {\n  /** Key of the account direct (non-pool) routes serve; the first login wins. */\n  default?: string\n  accounts: Record<string, S>\n  /** Old keys remain bound to their migrated account, never a workspace sibling. */\n  aliases?: Record<string, string>\n}\n\n/** The durable store shape: per provider, its accounts. */\nexport interface SessionMap {\n  codex?: ProviderAccounts<CodexSession>\n  claude?: ProviderAccounts<ClaudeSession>\n  grok?: ProviderAccounts<GrokSession>\n  copilot?: ProviderAccounts<CopilotSession>\n  antigravity?: ProviderAccounts<AntigravitySession>\n}\n\n/** Any stored session, for provider-agnostic plumbing. */\nexport type StoredSession = CodexSession | ClaudeSession | GrokSession | CopilotSession | AntigravitySession\n\n/** The session type one provider stores. */\nexport type SessionOf<K extends ProviderId> = NonNullable<SessionMap[K]>['accounts'][string]\n\n/** One account entry as returned by {@link listAccounts} (default first). */\nexport interface AccountEntry<S> {\n  key: string\n  session: S\n}\n\n/**\n * The stable identity of one session's account: Codex keys on workspace AND\n * user (email fallback, workspace-only for unidentified legacy sessions),\n * the others on their display identity, falling\n * back to a refresh-token hash for sessions stored before identity fields\n * existed. Logging the same account in again lands on the same key, so a\n * re-login updates in place instead of duplicating. (The hash fallback can\n * miss that dedup once for a legacy session re-logged with a now-known\n * identity — the duplicate is visible on the Settings page and can simply\n * be logged out.)\n * @param provider - the provider route.\n * @param session - the session to key.\n * @returns the account map key.\n */\nexport function accountKeyOf(provider: ProviderId, session: StoredSession): string {\n  switch (provider) {\n    case 'codex': {\n      const codex = session as CodexSession\n      const payload = typeof codex.idToken === 'string' ? decodeJwtPayload(codex.idToken) : undefined\n      const auth = claimObject(payload?.['https://api.openai.com/auth'])\n      const user = nonEmpty(auth?.chatgpt_user_id) ?? nonEmpty(auth?.user_id)\n      const profile = claimObject(payload?.['https://api.openai.com/profile'])\n      const email = nonEmpty(codex.emailAddress) ?? nonEmpty(payload?.email) ?? nonEmpty(profile?.email)\n      if (user === undefined && email === undefined) return codex.accountId\n      // JSON tuple encoding avoids separator collisions and distinguishes IDs from emails.\n      return JSON.stringify([codex.accountId, user === undefined ? 'email' : 'user', user ?? email!.toLowerCase()])\n    }\n    case 'claude':\n      return (session as ClaudeSession).emailAddress ?? tokenHash(session.refreshToken)\n    case 'grok':\n      return (session as GrokSession).account ?? tokenHash(session.refreshToken)\n    case 'antigravity':\n      return (session as AntigravitySession).account ?? tokenHash(session.refreshToken)\n    case 'copilot':\n      return (session as CopilotSession).account ?? tokenHash(session.refreshToken)\n  }\n}\n\nfunction nonEmpty(value: unknown): string | undefined {\n  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined\n}\n\nfunction claimObject(value: unknown): Record<string, unknown> | undefined {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n    ? value as Record<string, unknown> : undefined\n}\n\n/** Resolve only recorded aliases, not an ambiguous workspace-wide match. */\nfunction resolveAccount(entry: ProviderAccounts<StoredSession>, key: string): string {\n  const seen = new Set<string>()\n  while (!Object.hasOwn(entry.accounts, key)\n    && entry.aliases !== undefined\n    && Object.hasOwn(entry.aliases, key)\n    && !seen.has(key)) {\n    seen.add(key)\n    key = entry.aliases[key]\n  }\n  return key\n}\n\n/**\n * Resolve a Codex reference that is neither a stored key nor a recorded alias:\n * a config `account` may name the login email (as the other providers' keys\n * do) or the bare workspace ID that keys stored before per-user keys. Only an\n * unambiguous match resolves; two users sharing the workspace stay apart, and\n * the reference is returned unchanged so the caller reports it as missing.\n */\nfunction resolveCodexReference(entry: ProviderAccounts<CodexSession>, reference: string): string {\n  const wanted = reference.trim().toLowerCase()\n  if (wanted.length === 0) return reference\n  const matches = Object.entries(entry.accounts).filter(([, session]) =>\n    session.accountId === reference.trim() || codexEmail(session) === wanted)\n  return matches.length === 1 ? matches[0][0] : reference\n}\n\n/**\n * Resolve a persisted legacy account key to its canonical account identity.\n * For Codex, a reference that matches no key or alias also resolves through\n * a unique login email or workspace ID (see {@link resolveCodexReference}).\n */\nexport async function resolveAccountKey(\n  provider: ProviderId,\n  account: string,\n  path = authFilePath(),\n): Promise<string> {\n  const entry = (await loadStore(path))[provider]\n  if (entry === undefined) return account\n  const key = resolveAccount(entry, account)\n  if (provider === 'codex' && !Object.hasOwn(entry.accounts, key)) {\n    return resolveCodexReference(entry as ProviderAccounts<CodexSession>, key)\n  }\n  return key\n}\n\n/** Migrate workspace-only keys once; retain collisions rather than discard credentials. */\nfunction codexEmail(session: CodexSession): string | undefined {\n  const payload = typeof session.idToken === 'string' ? decodeJwtPayload(session.idToken) : undefined\n  const profile = claimObject(payload?.['https://api.openai.com/profile'])\n  return (nonEmpty(session.emailAddress) ?? nonEmpty(payload?.email) ?? nonEmpty(profile?.email))?.toLowerCase()\n}\n\nfunction codexUserKey(session: CodexSession): string | undefined {\n  const key = accountKeyOf('codex', session)\n  try {\n    const tuple = JSON.parse(key) as unknown\n    return Array.isArray(tuple) && tuple[1] === 'user' ? key : undefined\n  } catch {\n    return undefined\n  }\n}\n\n/** Upgrade one unambiguous email fallback to the stable user key. */\nfunction reconcileCodexIdentity(entry: ProviderAccounts<CodexSession>, session: CodexSession): string | undefined {\n  const userKey = codexUserKey(session)\n  const email = codexEmail(session)\n  if (userKey === undefined || email === undefined) return undefined\n  const emailKey = JSON.stringify([session.accountId, 'email', email])\n  const previous = entry.accounts[emailKey]\n  if (previous === undefined || codexEmail(previous) !== email) return undefined\n  // Never merge workspace-wide: the exact normalized workspace/email pair must match.\n  if (!Object.hasOwn(entry.accounts, userKey)) entry.accounts[userKey] = previous\n  delete entry.accounts[emailKey]\n  entry.aliases = { ...entry.aliases, [emailKey]: userKey }\n  for (const [alias, target] of Object.entries(entry.aliases)) {\n    if (target === emailKey) entry.aliases[alias] = userKey\n  }\n  if (entry.default === emailKey) entry.default = userKey\n  return userKey\n}\n\nfunction migrateCodex(entry: ProviderAccounts<CodexSession>): void {\n  for (const [oldKey, session] of Object.entries(entry.accounts)) {\n    if (oldKey !== session.accountId) continue\n    const key = accountKeyOf('codex', session)\n    if (key === oldKey || Object.hasOwn(entry.accounts, key)) continue\n    entry.accounts[key] = session\n    delete entry.accounts[oldKey]\n    entry.aliases = { ...entry.aliases, [oldKey]: key }\n    if (entry.default === oldKey) entry.default = key\n  }\n}\n\n/** Short stable hash for sessions without an identity field. */\nfunction tokenHash(refreshToken: string): string {\n  return `token-${createHash('sha256').update(refreshToken).digest('hex').slice(0, 16)}`\n}\n\n/**\n * Absolute path of the auth store file.\n * @returns `dshHomePath('plugins', 'subscriptions', 'auth.json')`.\n */\nexport function authFilePath(): string {\n  return dshHomePath('plugins', 'subscriptions', 'auth.json')\n}\n\n/** Store location used before the plugin was renamed; migrated on first read. */\nfunction legacyAuthFilePath(): string {\n  return dshHomePath('plugins', 'router', 'auth.json')\n}\n\n/** Check that one durable session carries the fields every session needs. */\nfunction assertSessionShape(provider: ProviderId, account: string, value: unknown): asserts value is StoredSession {\n  if (typeof value !== 'object' || value === null) {\n    throw new Error(`subscriptions auth store: entry \"${provider}/${account}\" is not an object; fix or delete the store file`)\n  }\n  const entry = value as Record<string, unknown>\n  if (typeof entry.accessToken !== 'string' || entry.accessToken.length === 0\n    || typeof entry.refreshToken !== 'string' || entry.refreshToken.length === 0\n    || typeof entry.expiresAt !== 'number' || !Number.isFinite(entry.expiresAt)) {\n    throw new Error(\n      `subscriptions auth store: entry \"${provider}/${account}\" is missing accessToken/refreshToken/expiresAt; fix or delete the store file`,\n    )\n  }\n  if (provider === 'antigravity'\n    && (typeof entry.projectId !== 'string' || entry.projectId.length === 0)) {\n    throw new Error(\n      'subscriptions auth store: entry \"antigravity\" is missing projectId; log out and complete Antigravity login again',\n    )\n  }\n}\n\n/**\n * Read the whole store. A missing file is an empty store; malformed JSON or a\n * malformed entry throws, because silently discarding tokens would strand the\n * user without a diagnosis. Single-account entries are migrated in memory;\n * the next write persists the new shape.\n * @param path - store file path; defaults to {@link authFilePath}.\n * @returns the parsed session map.\n */\nexport async function loadStore(path = authFilePath()): Promise<SessionMap> {\n  let text: string\n  try {\n    text = await readFile(path, 'utf8')\n  } catch (error) {\n    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error\n    // Migrate the pre-rename store once, preserving existing logins.\n    if (path !== authFilePath()) return {}\n    try {\n      text = await readFile(legacyAuthFilePath(), 'utf8')\n    } catch (legacyError) {\n      if ((legacyError as NodeJS.ErrnoException).code === 'ENOENT') return {}\n      throw legacyError\n    }\n    const migrated = parseStore(text, legacyAuthFilePath())\n    await writeStore(migrated, path)\n    await rm(legacyAuthFilePath(), { force: true })\n    return migrated\n  }\n  return parseStore(text, path)\n}\n\n/**\n * Parse and migrate store JSON read from `path`. An ACCOUNT entry whose shape\n * is invalid (empty or missing tokens — corruption seen in the wild from a\n * broken keychain import) is SKIPPED instead of rejected: one bad entry must\n * not blind every provider's status read, and a session without tokens is\n * unusable by definition, so nothing of value is discarded. The next write\n * persists the store without the skipped entry. Structural failures (invalid\n * JSON, a non-object file) still throw — those say the file itself is broken.\n */\nfunction parseStore(text: string, path: string): SessionMap {\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(text)\n  } catch {\n    throw new Error(`subscriptions auth store at ${path} is not valid JSON; fix or delete the file`)\n  }\n  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {\n    throw new Error(`subscriptions auth store at ${path} must be a JSON object keyed by provider; fix or delete the file`)\n  }\n  const raw = parsed as Record<string, unknown>\n  const store: SessionMap = {}\n  for (const provider of PROVIDER_IDS) {\n    const entry = raw[provider]\n    if (entry === undefined) continue\n    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {\n      console.warn(`subscriptions auth store: entry \"${provider}\" is not an object; skipped`)\n      continue\n    }\n    const record = entry as Record<string, unknown>\n    if (typeof record.accessToken === 'string') {\n      // Single-account format: wrap the bare session, preserving every field.\n      if (!isValidSessionShape(record)) {\n        console.warn(`subscriptions auth store: legacy entry \"${provider}\" has no usable tokens; skipped`)\n        continue\n      }\n      const session = record as unknown as StoredSession\n      const key = provider === 'codex' ? (session as CodexSession).accountId : accountKeyOf(provider, session)\n      ;(store as Record<string, unknown>)[provider] = { default: key, accounts: { [key]: session } }\n      continue\n    }\n    const accounts = record.accounts\n    if (typeof accounts !== 'object' || accounts === null || Array.isArray(accounts)) {\n      console.warn(`subscriptions auth store: entry \"${provider}\" has no accounts map; skipped`)\n      continue\n    }\n    if (record.default !== undefined && typeof record.default !== 'string') {\n      console.warn(`subscriptions auth store: entry \"${provider}\" default is not a string; skipped`)\n      continue\n    }\n    const kept: Record<string, StoredSession> = {}\n    for (const [account, session] of Object.entries(accounts)) {\n      if (isValidSessionShape(session)) {\n        kept[account] = session as StoredSession\n      } else {\n        console.warn(\n          `subscriptions auth store: entry \"${provider}/${account}\" has no usable accessToken/refreshToken/expiresAt; skipped`,\n        )\n      }\n    }\n    if (Object.keys(kept).length === 0) continue\n    const validDefault = record.default === undefined || record.default in kept\n      ? record.default as string | undefined\n      : Object.keys(kept)[0]\n    ;(store as Record<string, unknown>)[provider] = { ...record, default: validDefault, accounts: kept }\n  }\n  if (store.codex !== undefined) migrateCodex(store.codex)\n  return store\n}\n\n/** Whether a value carries the fields every stored session needs (non-empty tokens). */\nfunction isValidSessionShape(value: unknown): boolean {\n  if (typeof value !== 'object' || value === null) return false\n  const entry = value as Record<string, unknown>\n  return typeof entry.accessToken === 'string' && entry.accessToken.length > 0\n    && typeof entry.refreshToken === 'string' && entry.refreshToken.length > 0\n    && typeof entry.expiresAt === 'number' && Number.isFinite(entry.expiresAt)\n}\n\n/** Persist the whole store atomically with owner-only permissions. */\nasync function writeStore(store: SessionMap, path: string): Promise<void> {\n  await mkdir(dirname(path), { recursive: true })\n  const tmp = `${path}.tmp-${process.pid}-${Math.random().toString(36).slice(2)}`\n  try {\n    await writeFile(tmp, JSON.stringify(store, null, 2), { mode: 0o600 })\n    // An existing destination keeps its old mode through rename on some\n    // filesystems; enforce 0600 on the source before the swap.\n    await chmod(tmp, 0o600)\n    await rename(tmp, path)\n  } catch (error) {\n    await rm(tmp, { force: true })\n    throw error\n  }\n}\n\n/**\n * One write chain per store path. Every mutation is a read-modify-write of a\n * single JSON file, and the plugin has several independent writers — a login,\n * a logout, and one token refresh per provider account, each on its own\n * schedule. Overlapping them unserialized costs whichever account read the\n * store first its entry.\n *\n * A chain is dropped once nothing is queued behind it, so the map holds an\n * entry only while writes are in flight.\n */\nconst writeChains = new Map<string, Promise<unknown>>()\n\n/**\n * Run one read-modify-write of a store path after every write already queued\n * for it. Callers join the chain synchronously, so call order is write order.\n * @param path - the store file being mutated.\n * @param action - the read-modify-write to run.\n * @returns whatever `action` returns.\n */\nasync function serialize<T>(path: string, action: () => Promise<T>): Promise<T> {\n  const previous = writeChains.get(path) ?? Promise.resolve()\n  // Both handlers: a failed write must not strand everything queued behind it.\n  const next = previous.then(action, action)\n  const tail = next.then(() => undefined, () => undefined)\n  writeChains.set(path, tail)\n  try {\n    return await next\n  } finally {\n    if (writeChains.get(path) === tail) writeChains.delete(path)\n  }\n}\n\n/**\n * List one provider's accounts, default first.\n * @param provider - the provider route.\n * @param path - store file path; defaults to {@link authFilePath}.\n * @returns the account entries in stable order (empty when logged out).\n */\nexport async function listAccounts<K extends ProviderId>(\n  provider: K,\n  path = authFilePath(),\n): Promise<AccountEntry<SessionOf<K>>[]> {\n  const entry = (await loadStore(path))[provider]\n  if (entry === undefined) return []\n  const accounts = Object.entries(entry.accounts).map(([key, session]) => ({ key, session }))\n  accounts.sort((a, b) => Number(b.key === entry.default) - Number(a.key === entry.default))\n  return accounts\n}\n\n/**\n * Read one account's session.\n * @param provider - the provider route.\n * @param account - the account key; defaults to the provider's default account.\n * @param path - store file path; defaults to {@link authFilePath}.\n * @returns the stored session, or `undefined` when absent.\n */\nexport async function getAccountSession<K extends ProviderId>(\n  provider: K,\n  account?: string,\n  path = authFilePath(),\n): Promise<SessionOf<K> | undefined> {\n  const entry = (await loadStore(path))[provider]\n  if (entry === undefined) return undefined\n  const key = account ?? entry.default\n  if (key === undefined) return undefined\n  return entry.accounts[resolveAccount(entry, key)] as SessionOf<K> | undefined\n}\n\n/**\n * Write one account's session, preserving the others. The first account of a\n * provider becomes its default.\n *\n * The session is validated before it lands: a corrupt entry written here\n * would fail every later read of the whole store (one bad entry breaks all\n * providers' status), so the write path must be as strict as the read path.\n * @param provider - the provider route.\n * @param account - the account key (see {@link accountKeyOf}).\n * @param session - the fresh session from a login or refresh.\n * @param path - store file path; defaults to {@link authFilePath}.\n * @throws when the session is missing accessToken/refreshToken/expiresAt.\n */\nexport async function saveAccountSession<K extends ProviderId>(\n  provider: K,\n  account: string,\n  session: SessionOf<K>,\n  path = authFilePath(),\n): Promise<void> {\n  assertSessionShape(provider, account, session)\n  return serialize(path, async () => {\n    const store = await loadStore(path)\n    const entry = store[provider] as ProviderAccounts<SessionOf<K>> | undefined\n    if (entry !== undefined) {\n      account = resolveAccount(entry, account)\n      if (provider === 'codex') {\n        account = reconcileCodexIdentity(\n          entry as unknown as ProviderAccounts<CodexSession>,\n          session as unknown as CodexSession,\n        ) ?? accountKeyOf('codex', session as unknown as CodexSession)\n      }\n    }\n    ;(store as Record<string, unknown>)[provider] = {\n      ...entry,\n      default: entry?.default ?? account,\n      accounts: { ...entry?.accounts, [account]: session },\n    } satisfies ProviderAccounts<SessionOf<K>>\n    await writeStore(store, path)\n  })\n}\n\n/**\n * Delete one account's session (logout). Deleting the default moves the badge\n * to the next remaining account.\n * @param provider - the provider route.\n * @param account - the account key.\n * @param path - store file path; defaults to {@link authFilePath}.\n */\nexport async function deleteAccountSession(\n  provider: ProviderId,\n  account: string,\n  path = authFilePath(),\n): Promise<void> {\n  return serialize(path, async () => {\n    const store = await loadStore(path)\n    const entry = store[provider]\n    if (entry === undefined) return\n    account = resolveAccount(entry, account)\n    if (!Object.hasOwn(entry.accounts, account)) return\n    const accounts = { ...entry.accounts }\n    delete accounts[account]\n    if (Object.keys(accounts).length === 0) {\n      delete store[provider]\n    } else {\n      ;(store as Record<string, unknown>)[provider] = {\n        ...entry,\n        ...entry.default === account ? { default: Object.keys(accounts)[0] } : { default: entry.default },\n        accounts,\n      }\n    }\n    await writeStore(store, path)\n  })\n}\n\n/**\n * Pin the account direct (non-pool) routes serve.\n * @param provider - the provider route.\n * @param account - the account key; must exist.\n * @param path - store file path; defaults to {@link authFilePath}.\n */\nexport async function setDefaultAccount(\n  provider: ProviderId,\n  account: string,\n  path = authFilePath(),\n): Promise<void> {\n  return serialize(path, async () => {\n    const store = await loadStore(path)\n    const entry = store[provider]\n    if (entry !== undefined) account = resolveAccount(entry, account)\n    if (entry === undefined || !Object.hasOwn(entry.accounts, account)) {\n      throw new Error(`no ${provider} account \"${account}\" is logged in`)\n    }\n    ;(store as Record<string, unknown>)[provider] = { ...entry, default: account }\n    await writeStore(store, path)\n  })\n}\n"
